export default function App() {
  const api = useYumina();
  const v = api.variables || {};
  const num = (id, dflt) => (typeof v[id] === 'number' ? v[id] : dflt);
  const pc = v['pc'] || 'undecided';
  const phaseNames = {
    'coven-days': 'Coven Days',
    'wishwright-case': 'The Wishwright Case',
    founding: 'The Founding',
    'chapter-war': 'The Alden War',
    'blackmail-truce': 'The Blackmail Truce',
    aftermath: 'Aftermath'
  };
  const phase = phaseNames[v['story-phase']] || 'Coven Days';
  const trust = num('society-trust', 30);
  const fk = num('forbidden-knowledge', 0);
  const favor = num('daemon-favor', 10);
  const bloodline = num('witch-bloodline', 0);
  const summons = num('night-summons', 0);
  const erin = num('erin-trust', 0);

  const pct = (val, max) => Math.max(0, Math.min(100, (val / max) * 100));

  function Bar({ label, value, max, from, to, note }) {
    return (
      <div className={'' + 'rounded-lg border border-[#3a2f55] bg-[#171226] p-3'}>
        <div className={'flex items-baseline justify-between mb-1'}>
          <span className={'text-[11px] uppercase tracking-widest text-[#b8a9d9]'}>{label}</span>
          <span className={'text-[13px] font-semibold text-[#e6dff5]'}>{value}<span className={'text-[#7a6b9c]'}>/{max}</span></span>
        </div>
        <div className={'relative h-2 rounded-full bg-[#241b3d] overflow-visible'}>
          <div className={'h-2 rounded-full transition-all duration-700'} style={{ width: pct(value, max) + '%', background: 'linear-gradient(90deg, ' + from + ', ' + to + ')' }} />
          {note && <div className={'absolute right-0 top-3 text-[9px] text-[#6b5b93]'}>{note}</div>}
        </div>
      </div>
    );
  }

  const tiers = [ { at: 120, label: 'Curse' }, { at: 150, label: 'Origin' }, { at: 180, label: 'Elves' }, { at: 200, label: 'Rite' } ];

  return (
    <div className={'flex flex-col h-full min-h-0 bg-[#0d0a1a] text-[#e6dff5] font-sans'}>
      <header className={'flex items-center justify-between gap-3 border-b border-[#2c2247] bg-gradient-to-r from-[#140f26] to-[#1b1330] px-4 py-2.5'}>
        <div className={'flex items-center gap-2.5 min-w-0'}>
          <span className={'text-lg leading-none'}>🌙</span>
          <div className={'min-w-0'}>
            <div className={'text-[13px] font-semibold tracking-[0.18em] uppercase truncate'}>The Witch Society</div>
            <div className={'text-[10px] text-[#8a7ab0] tracking-wider'}>Narrows Chronicles</div>
          </div>
        </div>
        <div className={'flex items-center gap-2 shrink-0'}>
          {pc === 'undecided' ? (
            <span className={'rounded-full border border-[#4d3f76] bg-[#241b3d] px-2.5 py-1 text-[10px] uppercase tracking-widest text-[#b8a9d9] animate-pulse'}>Choose your Witch</span>
          ) : (
            <span className={'rounded-full border border-[#6d5aa6] bg-[#2a2050] px-2.5 py-1 text-[10px] uppercase tracking-widest text-[#d9cdf2]'}>{pc} Kessler Quinlan</span>
          )}
          <span className={'rounded-full border border-[#3d6b52] bg-[#15291f] px-2.5 py-1 text-[10px] uppercase tracking-widest text-[#9fd8bb]'}>{phase}</span>
        </div>
      </header>

      <div className={'flex flex-1 min-h-0'}>
        <aside className={'w-56 shrink-0 overflow-y-auto border-r border-[#2c2247] bg-[#100c1f] p-3 space-y-2.5 hidden md:flex md:flex-col'}>
          <div className={'text-[10px] uppercase tracking-[0.2em] text-[#7a6b9c] pb-1'}>Coven Standing</div>
          <Bar label={'Society Trust'} value={trust} max={100} from={'#7c5cbf'} to={'#c9a7ff'} />
          <div className={'' + 'rounded-lg border border-[#3a2f55] bg-[#171226] p-3'}>
            <div className={'flex items-baseline justify-between mb-1'}>
              <span className={'text-[11px] uppercase tracking-widest text-[#b8a9d9]'}>Forbidden Knowledge</span>
              <span className={'text-[13px] font-semibold text-[#e6dff5]'}>{fk}<span className={'text-[#7a6b9c]'}>/200</span></span>
            </div>
            <div className={'relative h-2 rounded-full bg-[#241b3d]'}>
              <div className={'h-2 rounded-full transition-all duration-700'} style={{ width: pct(fk, 200) + '%', background: 'linear-gradient(90deg, #d4a017, #ffd76e)' }} />
              {tiers.map(t => (
                <div key={t.at} className={'absolute top-0 h-2 flex items-center'} style={{ left: pct(t.at, 200) + '%' }}>
                  <div className={'absolute -top-0.5 -left-px w-0.5 h-3 ' + (fk >= t.at ? 'bg-[#ffd76e]' : 'bg-[#4d3f76]')} />
                  <div className={'absolute top-3 -left-2 text-[8px] ' + (fk >= t.at ? 'text-[#ffd76e]' : 'text-[#5d4f85]')}>{t.label}</div>
                </div>
              ))}
            </div>
            <div className={'text-[9px] text-[#6b5b93] pt-4'}>Tiers: the curse, the origin, the elves, the Rite</div>
          </div>
          <Bar label={'Daemon Favor'} value={favor} max={100} from={'#a33a3a'} to={'#ff7a7a'} note={'circle always closed'} />
          <Bar label={'Witch Bloodline'} value={bloodline} max={100} from={'#3f8f5f'} to={'#8fe0ae'} />
          <div className={'' + 'rounded-lg border border-[#3a2f55] bg-[#171226] p-3'}>
            <div className={'flex items-baseline justify-between mb-2'}>
              <span className={'text-[11px] uppercase tracking-widest text-[#b8a9d9]'}>Night Summons</span>
              <span className={'text-[13px] font-semibold text-[#e6dff5]'}>{summons}/5</span>
            </div>
            <div className={'flex gap-1.5'}>
              {[0,1,2,3,4].map(i => (
                <div key={i} className={'w-4 h-4 rounded-full border transition-all duration-500 ' + (i < summons ? 'border-[#ffd76e] bg-[#ffd76e] shadow-[0_0_6px_rgba(255,215,110,0.6)]' : 'border-[#4d3f76] bg-[#241b3d]')} />
              ))}
            </div>
            <div className={'text-[9px] text-[#6b5b93] mt-2'}>{summons >= 5 ? 'Daemons know you on sight.' : 'A running total. It never resets.'}</div>
          </div>
          <Bar label={"Erin's Trust"} value={erin} max={100} from={'#4a7fb5'} to={'#8fc7ff'} note={erin >= 81 ? 'part of the team' : 'strangers still'} />
        </aside>

        <main className={'flex-1 flex flex-col min-h-0 relative'}>
          <MessageList />
          <div className={'border-t border-[#2c2247] bg-[#100c1f]'}>
            <MessageInput />
          </div>
        </main>
      </div>
    </div>
  );
}
